CREATE TABLE IF NOT EXISTS pitlane.quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,actor_id uuid NOT NULL,input jsonb NOT NULL,inputs_hash text NOT NULL,expires_at timestamptz NOT NULL,units integer NOT NULL DEFAULT 1 CHECK(units=1),price_cents bigint NOT NULL DEFAULT 400 CHECK(price_cents>=0),policy_version text NOT NULL DEFAULT '1',consumed_job_id uuid,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,tenant_id) REFERENCES pitlane.projects(id,tenant_id),UNIQUE(id,tenant_id,project_id));
CREATE TABLE IF NOT EXISTS pitlane.entitlement_lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES pitlane.tenants,source_key text NOT NULL UNIQUE,granted integer NOT NULL CHECK(granted>=0),reserved integer NOT NULL DEFAULT 0,consumed integer NOT NULL DEFAULT 0,starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz NOT NULL,CHECK(reserved>=0 AND consumed>=0 AND consumed+reserved<=granted));
CREATE TABLE IF NOT EXISTS pitlane.budgets(key text PRIMARY KEY,maximum bigint NOT NULL CHECK(maximum>=0),reserved bigint NOT NULL DEFAULT 0,spent bigint NOT NULL DEFAULT 0,CHECK(reserved>=0 AND spent>=0 AND reserved+spent<=maximum));
CREATE TABLE IF NOT EXISTS pitlane.jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,quote_id uuid NOT NULL,input jsonb NOT NULL,canonical_key text NOT NULL,state text NOT NULL CHECK(state IN('awaiting_payment','queued','running','verifying','retry_wait','completed','unsupported','failed','expired','cancelled')),origin text NOT NULL CHECK(origin IN('fixture','internal','customer')),lot_id uuid REFERENCES pitlane.entitlement_lots,order_id uuid,deadline timestamptz NOT NULL,ready_at timestamptz NOT NULL DEFAULT now(),lease_owner text,lease_until timestamptz,lease_epoch bigint NOT NULL DEFAULT 0,attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),cancel_requested boolean NOT NULL DEFAULT false,cost_cap bigint NOT NULL DEFAULT 1000000,cost_used bigint NOT NULL DEFAULT 0,calls integer NOT NULL DEFAULT 0 CHECK(calls BETWEEN 0 AND 16),receipt_id uuid,event_seq bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,tenant_id) REFERENCES pitlane.projects(id,tenant_id),FOREIGN KEY(quote_id,tenant_id,project_id) REFERENCES pitlane.quotes(id,tenant_id,project_id),UNIQUE(tenant_id,project_id,canonical_key),UNIQUE(id,tenant_id,project_id));
CREATE TABLE IF NOT EXISTS pitlane.idempotency(tenant_id uuid,project_id uuid,key text CHECK(length(key) BETWEEN 16 AND 128),request_hash text NOT NULL,job_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,project_id,key),FOREIGN KEY(job_id,tenant_id,project_id) REFERENCES pitlane.jobs(id,tenant_id,project_id));
CREATE TABLE IF NOT EXISTS pitlane.job_events(tenant_id uuid,project_id uuid,job_id uuid,seq bigint,type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',occurred_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(job_id,seq),FOREIGN KEY(job_id,tenant_id,project_id) REFERENCES pitlane.jobs(id,tenant_id,project_id));
CREATE TABLE IF NOT EXISTS pitlane.cost_intents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,job_id uuid NOT NULL,lease_epoch bigint NOT NULL,provider_id text NOT NULL,method text NOT NULL CHECK(method IN('getGenesisHash','getAccountInfo','getSlot','getBlockTime')),maximum_micro bigint NOT NULL CHECK(maximum_micro>=0),status text NOT NULL DEFAULT 'uncertain' CHECK(status IN('uncertain','measured','reconciled')),response_bytes integer,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(job_id,tenant_id,project_id) REFERENCES pitlane.jobs(id,tenant_id,project_id));
CREATE INDEX IF NOT EXISTS jobs_claim ON pitlane.jobs(state,ready_at,deadline);
CREATE INDEX IF NOT EXISTS jobs_lease ON pitlane.jobs(lease_until) WHERE state IN('running','verifying');
DO $$ DECLARE n text; BEGIN FOREACH n IN ARRAY ARRAY['quotes','jobs','idempotency','job_events','cost_intents'] LOOP EXECUTE format('ALTER TABLE pitlane.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('DROP POLICY IF EXISTS scoped_read ON pitlane.%I',n);EXECUTE format('CREATE POLICY scoped_read ON pitlane.%I FOR SELECT USING(pitlane.can_project(tenant_id,project_id))',n);EXECUTE format('GRANT SELECT ON pitlane.%I TO pitlane_web',n);END LOOP; END $$;
ALTER TABLE pitlane.entitlement_lots ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS usage_read ON pitlane.entitlement_lots;
CREATE POLICY usage_read ON pitlane.entitlement_lots FOR SELECT USING(pitlane.can_tenant(tenant_id));
GRANT SELECT ON pitlane.entitlement_lots TO pitlane_web;
CREATE OR REPLACE FUNCTION pitlane.emit(j uuid,k text,p jsonb DEFAULT '{}') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE v pitlane.jobs; BEGIN UPDATE pitlane.jobs SET event_seq=event_seq+1 WHERE id=j RETURNING * INTO v; INSERT INTO pitlane.job_events(tenant_id,project_id,job_id,seq,type,payload) VALUES(v.tenant_id,v.project_id,j,v.event_seq,k,p); END $$;
